<script setup>
import { onMounted, reactive, ref, computed } from 'vue'
import { Servers, AddServer, CheckServer, RemoveServer, SwitchServer, SetConnection, Health, BaseImages, Images, Operations, VMs, Convert, CreateVM, VMAction, Snapshot, RuntimeStatus, InstallRuntime } from './api'

const tabs = [
  { id: 'overview', label: 'Dashboard', icon: '⌂' },
  { id: 'images', label: 'Images', icon: '◈' },
  { id: 'vms', label: 'Containers / MicroVMs', icon: '▣' },
  { id: 'convert', label: 'Convert / Build', icon: '⇄' },
]
const state = reactive({ tab: 'overview', connectionURL: '', source: 'alpine:latest', sourceType: 'oci', baseProfile: 'alpine', imageName: '', artifactDigest: '', vcpus: 1, memoryMiB: 512, selectedVM: null, vmPane: 'overview', serverID: '', showServerDialog: false, showServerManager: false, newServer: { name: 'Remote worker', url: 'https://worker.example.com', kind: 'remote', username: '', token: '' } })
const data = reactive({ health: null, baseImages: [], images: [], operations: [], vms: [], servers: [], message: '', runtime: { installed: false, firecracker: 'Not checked', jailer: 'Not checked', kvm: 'Not checked', tap: 'Not checked', kernel: 'Not checked', rootfs: 'Not checked', message: 'Install the local Firecracker runtime to begin' } })
const busy = ref(false)
const selectedVM = computed(() => data.vms.find(vm => vm.id === state.selectedVM) || data.vms[0])
async function refresh() { data.runtime = await RuntimeStatus(); if (!state.connectionURL) { data.message = data.runtime.installed ? 'Local runtime ready' : 'Install the local Firecracker runtime to begin'; return } try { data.health = await Health(); data.servers = await Servers() || []; data.baseImages = (await BaseImages()).images || []; data.images = (await Images()).images || []; data.operations = (await Operations()).operations || []; data.vms = (await VMs()).vms || []; state.serverID ||= data.servers.find(s => s.active)?.id || data.servers[0]?.id || ''; data.message = 'Connected to worker'; if (!state.selectedVM && data.vms[0]) state.selectedVM = data.vms[0].id } catch (err) { data.health = null; data.message = String(err) } }
async function installRuntime() { busy.value = true; try { data.message = 'Downloading and verifying Firecracker + jailer…'; data.runtime = await InstallRuntime(); data.message = data.runtime.installed ? 'Local Firecracker runtime installed' : data.runtime.message } catch (err) { data.message = `Runtime installation failed: ${String(err).replace(/^Error: /, '')}` } finally { busy.value = false } }
async function connect() { busy.value = true; try { await SetConnection(state.connectionURL, ''); await refresh() } finally { busy.value = false } }
async function copyText(text) { try { await navigator.clipboard.writeText(text); data.message = 'Copied to clipboard' } catch { data.message = 'Copy failed; select the command manually' } }
async function switchServer() { if (!state.serverID) return; busy.value = true; try { const server = await SwitchServer(state.serverID); state.connectionURL = server.url; await SetConnection(server.url, ''); await refresh() } catch (err) { data.message = String(err) } finally { busy.value = false } }
async function addServer() { busy.value = true; try { const token = state.newServer.token; const server = await AddServer(state.newServer.name, state.newServer.url, state.newServer.kind, state.newServer.username, token); data.servers = await Servers() || []; if (server.health === 'healthy') { data.message = `Connected to ${server.name}`; state.showServerDialog = false; state.serverID = server.id; state.connectionURL = server.url; await SetConnection(server.url, token); await SwitchServer(server.id); await refresh(); state.newServer = { name: 'Remote worker', url: 'https://worker.example.com', kind: 'remote', username: '', token: '' } } else { data.message = `Worker saved but is ${server.health}. Start the remote worker, then use Check again.` } } catch (err) { data.message = `Connection failed: ${String(err).replace(/^Error: /, '')}` } finally { busy.value = false } }
async function checkServer(id) { busy.value = true; try { const server = await CheckServer(id); data.servers = await Servers() || []; data.message = server.health === 'healthy' ? `Worker ${server.name} is healthy` : `Worker ${server.name} is ${server.health}`; if (server.health === 'healthy') { state.serverID = server.id; state.connectionURL = server.url; await SwitchServer(server.id); await refresh() } } catch (err) { data.message = `Health check failed: ${String(err).replace(/^Error: /, '')}` } finally { busy.value = false } }
async function removeServer(id) { busy.value = true; try { await RemoveServer(id); data.servers = await Servers() || []; if (state.serverID === id) { state.serverID = ''; state.connectionURL = ''; data.health = null } data.message = 'Server profile removed' } catch (err) { data.message = String(err) } finally { busy.value = false } }
async function convert() { busy.value = true; try { const op = await Convert(state.source, state.sourceType, state.baseProfile); data.message = `Conversion queued: ${op.id || 'created'}`; state.tab = 'convert'; await refresh() } catch (err) { data.message = String(err) } finally { busy.value = false } }
async function createVM() { busy.value = true; try { const vm = await CreateVM(state.artifactDigest, Number(state.vcpus), Number(state.memoryMiB)); data.message = `MicroVM created: ${vm.id || 'created'}`; state.selectedVM = vm.id; state.tab = 'vms'; await refresh() } catch (err) { data.message = String(err) } finally { busy.value = false } }
async function vmAction(id, action) { try { await VMAction(id, action); await refresh() } catch (err) { data.message = String(err) } }
async function snapshot(id, action) { try { await Snapshot(id, action, `${id}.snapshot`, `${id}.mem`); data.message = `${action} requested for ${id}`; state.tab = 'vms' } catch (err) { data.message = String(err) } }
function openVM(vm) { state.selectedVM = vm.id; state.tab = 'vms' }
onMounted(async () => { data.servers = await Servers() || []; const active = data.servers.find(s => s.active); if (active) { state.serverID = active.id; state.connectionURL = active.url } data.message = data.servers.length ? 'Select a worker and check health' : 'Add a worker URL to begin' })
</script>

<template>
  <div class="desktop-shell">
    <aside class="sidebar">
      <div class="brand"><span class="brand-mark">F</span><div><strong>Firecracker Studio</strong><small>microVM desktop</small></div></div>
      <div class="worker-card"><div class="worker-title"><span class="status-dot" :class="{ online: data.runtime.installed || data.health }"></span><span>{{ data.health ? 'Connected worker' : 'Local runtime' }}</span><span class="more">•••</span></div><strong>{{ data.health?.status || (data.runtime.installed ? 'Runtime ready' : 'Runtime not installed') }}</strong><small>{{ state.connectionURL || 'Managed locally by Studio' }}</small></div>
      <nav><button v-for="tab in tabs" :key="tab.id" :class="{ active: state.tab === tab.id }" @click="state.tab = tab.id"><span class="nav-icon">{{ tab.icon }}</span>{{ tab.label }}<span v-if="tab.id === 'vms' && data.vms.length" class="nav-count">{{ data.vms.length }}</span></button></nav>
      <div class="sidebar-bottom"><button class="connect-side" @click="installRuntime" :disabled="busy || data.runtime.installed">{{ busy ? 'Installing…' : (data.runtime.installed ? 'Runtime installed' : 'Install Firecracker') }}</button><button class="ghost small" @click="state.showServerDialog = true">Add remote worker</button><small>v1.0.0 · BlackLoverTech</small></div>
    </aside>
    <main class="main-area">
      <header class="topbar"><div><p class="eyebrow">{{ tabs.find(t => t.id === state.tab)?.label.toUpperCase() }}</p><h1>{{ state.tab === 'overview' ? 'Workspace overview' : tabs.find(t => t.id === state.tab)?.label }}</h1></div><div class="top-actions"><select v-model="state.serverID" class="switcher" @change="switchServer"><option v-for="server in data.servers" :key="server.id" :value="server.id">{{ server.kind === 'local' ? 'Local' : 'Remote' }}: {{ server.name }} · {{ server.health }}</option></select><button class="ghost" @click="state.showServerManager = true">Servers</button></div></header>
      <div class="content">
        <template v-if="state.tab === 'overview'">
          <section class="hero"><div><p class="eyebrow">FIRECRACKER CONTROL CENTER</p><h2>Run isolated workloads without the complexity.</h2><p>Convert OCI images, launch microVMs, and manage local or remote workers from one focused desktop workspace.</p></div><div class="hero-card"><span>Worker connection</span><strong>{{ data.health?.status || (data.runtime.installed ? 'Runtime ready' : 'Runtime not installed') }}</strong><small>{{ data.message }}</small><button v-if="!data.health" class="ghost small" @click="state.showServerDialog = true">Connect a worker</button></div></section>
          <section class="panel setup-card"><div><p class="eyebrow">FIRST RUN · LOCAL RUNTIME</p><h2>Install Firecracker on this computer</h2><p class="section-note">Studio manages the official Firecracker and jailer binaries locally. On Windows, the installer uses your WSL2 Ubuntu environment; on Linux, it installs into the Studio runtime directory.</p></div><div class="setup-actions"><button class="primary small" @click="installRuntime" :disabled="busy || data.runtime.installed">{{ data.runtime.installed ? 'Runtime installed' : (busy ? 'Installing…' : 'Install Firecracker') }}</button><button class="ghost small" @click="state.showServerDialog = true">Add remote worker</button></div><div class="setup-steps"><div class="setup-step"><span>01</span><div><strong>Install the runtime</strong><small>Studio downloads and verifies official Firecracker and jailer binaries.</small></div></div><div class="setup-step"><span>02</span><div><strong>Check host access</strong><small>Studio reports KVM, TAP/networking, kernel, and rootfs readiness.</small></div></div><div class="setup-step"><span>03</span><div><strong>Run microVMs</strong><small>Convert an OCI image and launch through the local socket-based runtime.</small></div></div></div></section><section class="metric-grid"><div class="metric"><span>MicroVMs</span><strong>{{ data.vms.length }}</strong><small>managed workloads</small></div><div class="metric"><span>Images</span><strong>{{ data.images.length + data.baseImages.length }}</strong><small>local and catalog</small></div><div class="metric"><span>Operations</span><strong>{{ data.operations.length }}</strong><small>conversion jobs</small></div><div class="metric"><span>Isolation</span><strong>Firecracker</strong><small>official socket API</small></div></section>
          <section class="grid two"><article class="panel"><div class="panel-head"><div><p class="eyebrow">QUICK START</p><h2>Convert an image</h2></div><span class="chip">OCI → microVM</span></div><label>Image or registry reference<input v-model="state.source" placeholder="alpine:latest" /></label><div class="form-row"><label>Source type<select v-model="state.sourceType"><option value="oci">OCI / Docker image</option><option value="dockerfile">Dockerfile</option><option value="archive">OCI archive</option></select></label><label>Guest base<select v-model="state.baseProfile"><option>alpine</option><option>debian</option><option>ubuntu</option></select></label></div><label class="name-field">Local image name<input v-model="state.imageName" placeholder="my-app:firecracker" /></label><button class="primary" @click="convert" :disabled="busy || !state.source">Start conversion</button></article><article class="panel"><div class="panel-head"><div><p class="eyebrow">HOST READINESS</p><h2>Local runtime readiness</h2></div><button class="ghost" @click="refresh">Check again</button></div><div class="check-row"><span>Firecracker binary</span><span class="state catalog">{{ data.runtime.firecracker }}</span></div><div class="check-row"><span>KVM access</span><span class="state catalog">{{ data.runtime.kvm }}</span></div><div class="check-row"><span>TAP networking</span><span class="state catalog">{{ data.runtime.tap }}</span></div><p class="hint">The local runtime is independent of Porter. Remote workers are optional and can be added only when you want to manage another host.</p></article></section>
          <section class="panel"><div class="panel-head"><div><p class="eyebrow">RECENT WORKLOADS</p><h2>MicroVMs</h2></div><button class="ghost" @click="state.tab = 'vms'">View all</button></div><div v-if="data.vms.length" class="table"><div v-for="vm in data.vms.slice(0, 4)" :key="vm.id" class="table-row"><span class="mono">{{ vm.id }}</span><span class="mono truncate">{{ vm.artifactDigest }}</span><span class="state" :class="vm.state">{{ vm.state }}</span><button class="ghost" @click="openVM(vm)">Open</button></div></div><div v-else class="empty">No microVMs yet. Convert an image or pull one from the marketplace.</div></section>
        </template>
        <template v-else-if="state.tab === 'vms'"><section class="toolbar"><div><p class="eyebrow">WORKLOADS</p><h2>MicroVM instances</h2></div><button class="primary small" @click="state.tab = 'images'">Create from image</button></section><div class="vm-layout"><section class="panel vm-list"><div v-if="data.vms.length" v-for="vm in data.vms" :key="vm.id" class="vm-list-row" :class="{ selected: selectedVM?.id === vm.id }" @click="openVM(vm)"><span class="vm-avatar">▣</span><div><strong>{{ vm.id.slice(0, 12) }}</strong><small>{{ vm.artifactDigest }}</small></div><span class="state" :class="vm.state">{{ vm.state }}</span></div><div v-else class="empty">No microVMs available.</div></section><section class="panel detail-panel"><div v-if="selectedVM"><div class="panel-head"><div><p class="eyebrow">MICROVM DETAIL</p><h2>{{ selectedVM.id }}</h2></div><span class="state" :class="selectedVM.state">{{ selectedVM.state }}</span></div><div class="detail-grid"><div><span>Artifact</span><strong class="mono">{{ selectedVM.artifactDigest }}</strong></div><div><span>Created</span><strong>{{ selectedVM.createdAt }}</strong></div><div><span>Resources</span><strong>{{ state.vcpus }} vCPU · {{ state.memoryMiB }} MiB</strong></div><div><span>Network</span><strong>Private TAP · NAT</strong></div></div><div class="action-row"><button class="primary small" @click="vmAction(selectedVM.id, 'start')">Start</button><button class="ghost" @click="vmAction(selectedVM.id, 'stop')">Stop</button><button class="ghost" @click="snapshot(selectedVM.id, 'create')">Snapshot</button><button class="ghost" @click="state.tab = 'logs'">View logs</button><button class="ghost" @click="state.tab = 'terminal'">Terminal</button></div></div><div v-else class="empty">Select a microVM to inspect it.</div></section></div></template>
        <template v-else-if="state.tab === 'images'"><section class="toolbar"><div><p class="eyebrow">IMAGE LIBRARY</p><h2>Local and converted images</h2></div><button class="primary small" @click="state.tab = 'marketplace'">Browse marketplace</button></section><section class="grid two"><article class="panel"><div class="panel-head"><div><p class="eyebrow">PULL OR CONVERT</p><h2>Docker / OCI image</h2></div></div><label>Image reference<input v-model="state.source" placeholder="postgres:17-alpine" /></label><label>Local name<input v-model="state.imageName" placeholder="postgres-firecracker:17" /></label><button class="primary" @click="convert">Pull and convert locally</button></article><article class="panel"><div class="panel-head"><div><p class="eyebrow">LOCAL ARTIFACTS</p><h2>Imported images</h2></div></div><div v-for="image in data.images" :key="image.digest" class="operation"><span class="chip">{{ image.sourceType }}</span><span class="truncate">{{ image.reference }}</span><span class="mono">{{ image.digest?.slice(0, 16) }}</span></div><div v-if="!data.images.length" class="empty">No local images yet.</div></article></section></template>
        <template v-else-if="state.tab === 'convert'"><section class="toolbar"><div><p class="eyebrow">IMAGE PIPELINE</p><h2>Convert or build a Firecracker image</h2></div></section><section class="grid two"><article class="panel"><div class="panel-head"><div><p class="eyebrow">DOCKER / OCI</p><h2>Pull and convert</h2></div><span class="chip">BuildKit</span></div><label>Image, Dockerfile, or Compose source<input v-model="state.source" placeholder="postgres:17-alpine or ./Dockerfile" /></label><div class="form-row"><label>Source type<select v-model="state.sourceType"><option value="oci">OCI / Docker image</option><option value="dockerfile">Dockerfile</option><option value="compose">Docker Compose</option></select></label><label>Guest base<select v-model="state.baseProfile"><option>alpine</option><option>debian</option><option>ubuntu</option></select></label></div><label class="name-field">Name the resulting microVM image<input v-model="state.imageName" placeholder="my-postgres:firecracker" /></label><button class="primary" @click="convert">Build Firecracker image</button></article><article class="panel"><p class="eyebrow">BUILD OUTPUT</p><h2>Operations</h2><div v-for="op in data.operations.slice().reverse()" :key="op.id" class="operation"><span class="state" :class="op.state">{{ op.state }}</span><span class="truncate">{{ op.request?.source }}</span><span class="mono">{{ op.id?.slice(0, 8) }}</span></div><div v-if="!data.operations.length" class="empty">No conversion operations yet.</div></article></section></template>
        <template v-else-if="state.tab === 'marketplace'"><section class="toolbar"><div><p class="eyebrow">GITHUB-BACKED CATALOG</p><h2>Firecracker marketplace</h2></div><span class="chip">{{ data.baseImages.length }} profiles</span></section><p class="section-note">Curated, versioned Firecracker-compatible bases. Select a base for conversion or pull a prebuilt artifact when the worker has downloaded and verified it.</p><div class="market-grid"><article v-for="image in data.baseImages" :key="image.id" class="market-card"><div class="base-top"><strong>{{ image.distribution }} {{ image.version }}</strong><span class="chip">{{ image.architecture }}</span></div><p class="mono">{{ image.id }}</p><div class="base-meta"><span>{{ image.kernelChannel }} kernel</span><span>{{ image.rootfsFormat }}</span><span>{{ image.initSystem }}</span></div><span class="state catalog">{{ image.status }}</span><button class="ghost full" @click="state.baseProfile = image.distribution; state.tab = 'images'">Use for conversion</button></article></div></template>
        <template v-else-if="state.tab === 'logs'"><section class="toolbar"><div><p class="eyebrow">OBSERVABILITY</p><h2>Live running logs</h2></div><span class="chip">streaming</span></section><section class="terminal-panel"><div class="terminal-head"><span class="status-dot online"></span> firecracker-studio-worker <span class="terminal-muted">/var/log/firecracker</span></div><pre>[ready] Firecracker Studio operation stream
[info] Connect a Linux or WSL2 worker to stream live VM logs
[info] Conversion and lifecycle events will appear here
[hint] Select a microVM and open Terminal for an interactive session</pre></section></template>
        <template v-else-if="state.tab === 'terminal'"><section class="toolbar"><div><p class="eyebrow">MICROVM CONSOLE</p><h2>Live terminal</h2></div><span class="chip">serial console</span></section><section class="terminal-panel tall"><div class="terminal-head"><span class="status-dot online"></span> {{ selectedVM?.id || 'no-vm-selected' }} <span class="terminal-muted">connected over guest console</span></div><pre>Firecracker Studio terminal
$ Waiting for a running microVM...
$ Use Start from the MicroVMs tab to open a guest console.</pre><div class="terminal-input"><span>$</span><input placeholder="Type a command when the guest is running..." /></div></section></template>
        <template v-else-if="state.tab === 'files'"><section class="toolbar"><div><p class="eyebrow">GUEST FILESYSTEM</p><h2>File manager</h2></div><button class="ghost">Upload</button></section><section class="panel empty large">Select a running microVM to browse its guest filesystem. File access will use the authenticated guest-agent channel.</section></template>
        <template v-else-if="state.tab === 'ssh'"><section class="toolbar"><div><p class="eyebrow">ACCESS</p><h2>SSH and connection details</h2></div></section><section class="grid two"><article class="panel"><p class="eyebrow">WORKER URL</p><h2>{{ state.connectionURL }}</h2><p class="section-note">This desktop app can connect to a local WSL2/Linux worker or an authenticated remote worker endpoint.</p><button class="ghost">Copy connection command</button></article><article class="panel"><p class="eyebrow">GUEST ACCESS</p><h2>SSH keys</h2><p class="section-note">Guest keys and serial-console access will be provisioned by the worker profile, never embedded into an image.</p><button class="ghost">Manage keys</button></article></section></template>
        <template v-else-if="state.tab === 'snapshots'"><section class="toolbar"><div><p class="eyebrow">RECOVERY</p><h2>Snapshots and restore</h2></div><button class="ghost" @click="refresh">Refresh</button></section><section class="panel empty large">No snapshots are registered yet. Create one from a running microVM to make it available here.</section></template>
        <template v-else><section class="toolbar"><div><p class="eyebrow">CONFIGURATION</p><h2>Settings</h2></div></section><section class="grid two"><article class="panel"><p class="eyebrow">LOCAL BACKEND</p><h2>WSL2 / Linux worker</h2><p class="section-note">The desktop UI is cross-platform. Firecracker execution runs in Linux with KVM and TAP access, directly on Linux or through managed WSL2 on Windows.</p><button class="ghost">Run diagnostics</button></article><article class="panel"><p class="eyebrow">REMOTE WORKER</p><h2>Secure connection</h2><label>Worker URL<input v-model="state.connectionURL" /></label><label>Bearer token<input type="password" placeholder="Stored in OS keychain" /></label><button class="primary" @click="connect">Save and connect</button></article></section></template>
      </div>
    </main>
    <div v-if="state.showServerManager" class="modal-backdrop" @click.self="state.showServerManager = false"><section class="modal panel server-manager"><div class="panel-head"><div><p class="eyebrow">CONNECTIONS</p><h2>Servers and workers</h2></div><button class="ghost" @click="state.showServerManager = false">×</button></div><p class="section-note">Add a local WSL2/Linux or remote worker URL. Studio never starts or repairs the worker automatically; it only checks health and switches to healthy servers.</p><div v-for="server in data.servers" :key="server.id" class="server-row"><div><strong>{{ server.name }}</strong><small>{{ server.kind === 'local' ? 'Local worker' : 'Remote worker' }} · {{ server.url }}</small></div><span class="state" :class="server.health">{{ server.health }}</span><button class="ghost small" @click="checkServer(server.id)">Check</button><button class="primary small" :disabled="server.health !== 'healthy'" @click="state.serverID = server.id; switchServer(); state.showServerManager = false">Use</button><button class="ghost small danger" @click="removeServer(server.id)">Remove</button></div><div class="manager-actions"><button class="primary small" @click="state.showServerManager = false; state.showServerDialog = true">+ Add server</button><button class="ghost small" @click="state.showServerManager = false">Done</button></div></section></div>
    <div v-if="state.showServerDialog" class="modal-backdrop" @click.self="state.showServerDialog = false"><form class="modal panel" @submit.prevent="addServer"><div class="panel-head"><div><p class="eyebrow">NEW WORKER</p><h2>Connect a server</h2></div><button type="button" class="ghost" @click="state.showServerDialog = false">×</button></div><p class="section-note">Start the worker manually first, then enter its URL. Use local for WSL2/Linux or remote for an authenticated endpoint. The URL is checked before it can be selected.</p><label>Name<input v-model="state.newServer.name" required placeholder="Production worker" /></label><label>Worker URL<input v-model="state.newServer.url" required placeholder="http://127.0.0.1:8080 or https://worker.example.com" /></label><label>Type<select v-model="state.newServer.kind"><option value="local">Local</option><option value="remote">Remote</option></select></label><label>Username (optional)<input v-model="state.newServer.username" placeholder="admin" /></label><label>Bearer token<input v-model="state.newServer.token" type="password" placeholder="Stored securely by the desktop app" /></label><div class="action-row"><button type="button" class="ghost" @click="state.showServerDialog = false">Cancel</button><button class="primary small" :disabled="busy">{{ busy ? 'Checking worker…' : 'Check health and add' }}</button></div></form></div>
  </div>
</template>
